import React, { useState, useEffect } from 'react';
import { CssBaseline, ThemeProvider, createTheme } from '@mui/material';
import { Routes, Route } from 'react-router-dom';
import axios from 'axios';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import StockPage from './pages/StockPage';
import FinancePage from './pages/FinancePage';
import InvoicePage from './pages/InvoicePage';
import DashboardPage from './components/Dashboard';
import './App.css';

const theme = createTheme({
  palette: {
    primary: { main: '#2c3e50' },
    secondary: { main: '#3498db' },
    background: { default: '#f5f5f5' },
  },
  typography: { fontFamily: '"Segoe UI", Tahoma, Geneva, Verdana, sans-serif' },
});

function App() {
  const [transactions, setTransactions] = useState([]);
  const [text, setText] = useState('');
  const [amount, setAmount] = useState('');

  useEffect(() => {
    fetchTransactions();
  }, []);

  const fetchTransactions = async () => {
    try {
      const res = await axios.get('http://localhost:5000/api/transactions');
      setTransactions(res.data);
    } catch (error) {
      console.error("Error fetching transactions:", error);
    }
  };

  const addTransaction = async (e) => {
    e.preventDefault();
    try {
      const newTransaction = { text, amount: parseFloat(amount) };
      await axios.post('http://localhost:5000/api/transactions', newTransaction);
      fetchTransactions();
      setText('');
      setAmount('');
    } catch (error) {
      console.error("Error adding transaction:", error);
    }
  };

  const deleteTransaction = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/transactions/${id}`);
      fetchTransactions();
    } catch (error) {
      console.error("Error deleting transaction:", error);
    }
  };

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Navbar />
      <Routes>
        <Route path="/" element={<HomePage />} />
        <Route path="/stock" element={<StockPage />} />
        <Route path="/finance" element={<FinancePage />} />
        <Route path="/invoice" element={<InvoicePage />} />
        <Route path="/dashboard" element={<DashboardPage />} />
      </Routes>

      {/* ✅ Transactions Section */}
      <div className="container">
        <h2>Income-Expense Manager</h2>
        <ul>
          {transactions.map((transaction) => (
            <li key={transaction.id}>
              {transaction.text} - ${transaction.amount}
              <button onClick={() => deleteTransaction(transaction.id)}>X</button>
            </li>
          ))}
        </ul>
        <form onSubmit={addTransaction}>
          <input 
            type="text" 
            value={text} 
            onChange={(e) => setText(e.target.value)} 
            placeholder="Enter text" 
            required 
          />
          <input 
            type="number" 
            value={amount} 
            onChange={(e) => setAmount(e.target.value)} 
            placeholder="Enter amount" 
            required 
          />
          <button type="submit">Add Transaction</button>
        </form>
      </div>
    </ThemeProvider>
  );
}

export default App;
